            }
            else if (c == '\'')
            {
                result.Append(source[i++]);
                while (i < source.Length && source[i] != '\'' && source[i] != '\n')
                {
                    if (source[i] == '\\' && i + 1 < source.Length)
                        Blank(result, source[i++]);
                    Blank(result, source[i++]);
                }

                if (i < source.Length && source[i] == '\'')
                    result.Append(source[i++]);
            }
            else
            {
